program.compute:
options = read('/input/options')
ids = []
# We try all combinations from min_count to max_count
from itertools import combinations
min_c = goal['min_count']
max_c = goal['max_count']
cover_tags = goal['cover'].get('tags', [])
sum_bounds = goal.get('sum_bounds', {})
cost_max = sum_bounds.get('cost', {}).get('max', None)

# We will try combinations of options satisfying the constraints
for count in range(min_c, max_c+1):
    for combo in combinations(options, count):
        candidate_ids = [opt['id'] for opt in combo]
        # Check coverage of tags
        tags_covered = []
        for opt in combo:
            tags_covered += opt.get('tags', [])
        tags_covered = list(set(tags_covered))
        # Check if all required tags covered
        if not all(tag in tags_covered for tag in cover_tags):
            continue
        # Check sum_bounds cost max
        total_cost = sum(opt.get('cost', 0) for opt in combo)
        if cost_max is not None and total_cost > cost_max:
            continue
        # Check requires closed dependencies if required
        if goal.get('closed_dependencies', False):
            # Each requires must be in candidate_ids
            valid_requires = True
            for opt in combo:
                for req in opt.get('requires', []):
                    if req not in candidate_ids:
                        valid_requires = False
                        break
                if not valid_requires:
                    break
            if not valid_requires:
                continue
        # Check no_conflicts
        if goal.get('no_conflicts', False):
            conflict_found = False
            for opt in combo:
                for conflict in opt.get('conflicts', []):
                    if conflict in candidate_ids:
                        conflict_found = True
                        break
                if conflict_found:
                    break
            if conflict_found:
                continue
        # Check unique fields if any
        unique_fields = goal.get('unique', [])
        unique_ok = True
        for field in unique_fields:
            vals = [opt.get(field) for opt in combo]
            if len(vals) != len(set(vals)):
                unique_ok = False
                break
        if not unique_ok:
            continue
        # Check order_by ascending lexicographic if any
        order_by = goal.get('order_by', [])
        if order_by:
            # Sort by order_by fields
            sorted_combo = sorted(combo, key=lambda x: tuple(x.get(f, '') for f in order_by))
            if [opt['id'] for opt in sorted_combo] != candidate_ids:
                continue
        # Check valid(candidate_ids)
        if valid(candidate_ids):
            ids = candidate_ids
            break
    if ids:
        break
result = ids

